namespace DevExpress.Images;

public class ImageResourceCache
{
	private readonly Dictionary<string, Stream> resources;

	private readonly Dictionary<string, Stream> resourcesByFileName;

	private readonly Dictionary<string, Dictionary<string, Stream>> categoryResources;

	private readonly IList<string> svgImages;

	private readonly Dictionary<ImageResourceKey, string> imageResourceKeyCache;

	private readonly object imageResourceKeyCacheSyncObj = new object();

	private static ImageResourceCache defaultCore;

	[ThreadStatic]
	private static SvgImageCache svgImageCache;

	[ThreadStatic]
	private static SvgRenderedImageCache svgRenderedImageCache;

	private readonly object loadSvgImageSyncObj = new object();

	public static ImageResourceCache Default
	{
		get
		{
			if (defaultCore == null)
			{
				defaultCore = DoLoad();
			}
			return defaultCore;
		}
	}

	protected internal IList<string> SvgImages => svgImages;

	protected ImageResourceCache()
	{
		resources = new Dictionary<string, Stream>(8192);
		resourcesByFileName = new Dictionary<string, Stream>(8192, StringComparer.OrdinalIgnoreCase);
		categoryResources = new Dictionary<string, Dictionary<string, Stream>>(64, StringComparer.OrdinalIgnoreCase);
		svgImages = new List<string>(3072);
		imageResourceKeyCache = new Dictionary<ImageResourceKey, string>();
	}

	public Image GetImage(string resourceName)
	{
		Stream resource = GetResource(resourceName);
		if (resource == null)
		{
			return null;
		}
		return Image.FromStream(resource);
	}

	public DXImage GetDXImage(string resourceName)
	{
		Stream resource = GetResource(resourceName);
		if (resource == null)
		{
			return null;
		}
		return DXImage.FromStream(resource);
	}

	public Image GetImageById(string id, ImageSize imageSize, ImageType imageType)
	{
		string text = FindResourceKey(id, imageSize, imageType);
		if (!string.IsNullOrEmpty(text))
		{
			if (imageType == ImageType.Svg || imageType == ImageType.Blazor)
			{
				return GetSvgImage(text, null, ConvertToSize(imageSize));
			}
			return GetImage(text);
		}
		return null;
	}

	public DXImage GetDXImageById(string id, ImageSize imageSize, ImageType imageType)
	{
		string text = FindResourceKey(id, imageSize, imageType);
		if (!string.IsNullOrEmpty(text))
		{
			if (imageType == ImageType.Svg || imageType == ImageType.Blazor)
			{
				return GetSvgDXImage(text, null, ConvertToSize(imageSize));
			}
			return GetDXImage(text);
		}
		return null;
	}

	private string FindResourceKey(string id, ImageSize imageSize, ImageType imageType)
	{
		ImageCacheUtils.ExtractPrefix(ref id, out var prefix);
		string fileName = ImageCacheUtils.GetFileName(id.ToLowerInvariant(), imageSize, imageType);
		string category = ImageCacheUtils.GetCategory(imageType);
		string text = FindResourceKey(fileName, category, prefix);
		if (string.IsNullOrEmpty(text) && !string.IsNullOrEmpty(prefix))
		{
			text = FindResourceKey(fileName, category, string.Empty);
		}
		return text;
	}

	private string FindResourceKey(string fileName, string category, string prefix)
	{
		ImageResourceKey key = new ImageResourceKey(fileName, prefix, category);
		lock (imageResourceKeyCacheSyncObj)
		{
			if (!imageResourceKeyCache.TryGetValue(key, out var value))
			{
				value = FindResourceKeyCore(fileName, category, prefix);
				imageResourceKeyCache.Add(key, value);
			}
			return value;
		}
	}

	private string FindResourceKeyCore(string fileName, string category, string prefix)
	{
		return resources.Keys.Where((string key) => ImageCacheUtils.IsMatch(key, prefix, fileName, category)).FirstOrDefault();
	}

	private string GetSvgImageResourceKey(string id)
	{
		ImageCacheUtils.ExtractPrefix(ref id, out var prefix);
		string fileName = ImageCacheUtils.GetFileName(id.ToLowerInvariant(), ImageSize.Any, ImageType.Svg);
		return FindResourceKey(fileName, "svgimages", prefix);
	}

	private static Size ConvertToSize(ImageSize imageSize)
	{
		return imageSize switch
		{
			ImageSize.Size16x16 => new Size(16, 16), 
			ImageSize.Size32x32 => new Size(32, 32), 
			_ => new Size(32, 32), 
		};
	}

	public void ResetSvgCache()
	{
		if (svgRenderedImageCache != null)
		{
			svgRenderedImageCache.Clear();
		}
	}

	public Image GetSvgImageById(string id, ISvgPaletteProvider paletteProvider, int width, int height)
	{
		string svgImageResourceKey = GetSvgImageResourceKey(id);
		if (string.IsNullOrEmpty(svgImageResourceKey))
		{
			return null;
		}
		return GetSvgImage(svgImageResourceKey, paletteProvider, new Size(width, height));
	}

	public Image GetSvgImage(string id, ISvgPaletteProvider paletteProvider, Size imageSize)
	{
		return GetSvgAsTImage(id, paletteProvider, imageSize, SvgRenderToImage);
	}

	public DXImage GetSvgDXImageById(string id, ISvgPaletteProvider paletteProvider, int width, int height)
	{
		string svgImageResourceKey = GetSvgImageResourceKey(id);
		if (string.IsNullOrEmpty(svgImageResourceKey))
		{
			return null;
		}
		return GetSvgDXImage(svgImageResourceKey, paletteProvider, new Size(width, height));
	}

	public DXImage GetSvgDXImage(string id, ISvgPaletteProvider paletteProvider, Size imageSize)
	{
		return GetSvgAsTImage(id, paletteProvider, imageSize, SvgRenderToDXImage);
	}

	private Image SvgRenderToImage(SvgBitmap svgBitmap, ISvgPaletteProvider paletteProvider, Size imageSize)
	{
		return svgBitmap.Render(imageSize, paletteProvider);
	}

	private DXImage SvgRenderToDXImage(SvgBitmap svgBitmap, ISvgPaletteProvider paletteProvider, Size imageSize)
	{
		return svgBitmap.RenderDXImage(imageSize, paletteProvider);
	}

	private TImage GetSvgAsTImage<TImage>(string id, ISvgPaletteProvider paletteProvider, Size imageSize, Func<SvgBitmap, ISvgPaletteProvider, Size, TImage> render) where TImage : IDisposable
	{
		SvgBitmap svgBitmap = GetSvgBitmap<TImage>(id);
		if (svgBitmap == null)
		{
			return default(TImage);
		}
		if (svgRenderedImageCache == null)
		{
			svgRenderedImageCache = new SvgRenderedImageCache();
		}
		SvgImageKey key = new SvgImageKey(id + typeof(TImage).Name, imageSize, paletteProvider);
		if (!svgRenderedImageCache.TryGetValue(key, out IDisposable value))
		{
			Size arg = (imageSize.IsEmpty ? new Size((int)svgBitmap.SvgImage.Width, (int)svgBitmap.SvgImage.Height) : imageSize);
			value = render(svgBitmap, paletteProvider, arg);
			svgRenderedImageCache.Add(key, value);
		}
		return (TImage)value;
	}

	public SvgImage GetSvgImageById(string id)
	{
		string svgImageResourceKey = GetSvgImageResourceKey(id);
		if (svgImageResourceKey == null)
		{
			return null;
		}
		return GetSvgImage(svgImageResourceKey);
	}

	public SvgImage GetSvgImageByFileNameAndCategory(string fileName, string category)
	{
		string text = "svgimages/" + category.ToLowerInvariant() + "/" + fileName.ToLowerInvariant();
		if (svgImageCache == null)
		{
			svgImageCache = new SvgImageCache();
		}
		if (!svgImageCache.TryGetValue(text, out var value))
		{
			SvgImage svgImage = LoadSvgImage(text);
			if (svgImage == null)
			{
				string resourceFileName = "svgimages\\" + fileName.ToLowerInvariant();
				svgImage = LoadSvgImageByResourceFileName(resourceFileName);
			}
			if (svgImage == null)
			{
				return null;
			}
			value = SvgBitmap.Create(svgImage);
			svgImageCache.Add(text, value);
		}
		return value.SvgImage;
	}

	public SvgImage GetSvgImage(string resourceName)
	{
		return GetSvgBitmap<SvgImage>(resourceName)?.SvgImage;
	}

	private SvgBitmap GetSvgBitmap<TImage>(string id)
	{
		if (svgImageCache == null)
		{
			svgImageCache = new SvgImageCache();
		}
		string key = id + typeof(TImage).Name;
		if (!svgImageCache.TryGetValue(key, out var value))
		{
			SvgImage svgImage = LoadSvgImage(id);
			if (svgImage == null)
			{
				return null;
			}
			value = SvgBitmap.Create(svgImage);
			svgImageCache.Add(key, value);
		}
		return value;
	}

	private SvgImage LoadSvgImage(string resourceName)
	{
		if (string.IsNullOrEmpty(resourceName))
		{
			return null;
		}
		if (!resources.TryGetValue(resourceName, out var value))
		{
			return null;
		}
		return LoadSvgImageCore(value);
	}

	private SvgImage LoadSvgImageByResourceFileName(string resourceFileName)
	{
		if (string.IsNullOrEmpty(resourceFileName))
		{
			return null;
		}
		if (!resourcesByFileName.TryGetValue(resourceFileName, out var value))
		{
			return null;
		}
		return LoadSvgImageCore(value);
	}

	private SvgImage LoadSvgImageCore(Stream resource)
	{
		lock (loadSvgImageSyncObj)
		{
			if (resource.CanSeek)
			{
				resource.Seek(0L, SeekOrigin.Begin);
			}
			return SvgLoader.LoadFromStream(resource);
		}
	}

	public Stream GetResource(string resourceName)
	{
		if (resourceName == null || !resources.TryGetValue(resourceName, out var value))
		{
			return null;
		}
		return value;
	}

	public Stream GetResourceByFileName(string fileName, ImageType imageType = ImageType.Colored)
	{
		if (fileName == null || !resourcesByFileName.TryGetValue(ImageCacheUtils.GetCategory(imageType) + "\\" + fileName, out var value))
		{
			return null;
		}
		return value;
	}

	[EditorBrowsable(EditorBrowsableState.Never)]
	public Stream GetSvgImageByCategory(string category, string fileName)
	{
		if (categoryResources.TryGetValue(category.ToLowerInvariant(), out var value) && value.TryGetValue(fileName.ToLowerInvariant(), out var value2))
		{
			return value2;
		}
		if (fileName == null || !resourcesByFileName.TryGetValue("svgimages\\" + fileName, out value2))
		{
			return null;
		}
		return value2;
	}

	internal ICollection GetKeys()
	{
		return resources.Keys;
	}

	[EditorBrowsable(EditorBrowsableState.Never)]
	public string[] GetAllResourceKeys()
	{
		if (resources.Keys.Count != 0)
		{
			return resources.Keys.ToArray();
		}
		return null;
	}

	[SecuritySafeCritical]
	private static ImageResourceCache DoLoad()
	{
		ImageResourceCache imageResourceCache = new ImageResourceCache();
		using IAssemblyImageReader assemblyImageReader = AssemblyImageReaderFactory.Create();
		IDictionaryEnumerator streamEnumerator = assemblyImageReader.GetStreamEnumerator();
		while (streamEnumerator.MoveNext())
		{
			string text = streamEnumerator.Key as string;
			if (text.EndsWith(".png", StringComparison.Ordinal))
			{
				imageResourceCache.resources.Add(text, (Stream)streamEnumerator.Value);
				string[] array = ImageCacheUtils.Split(text);
				text = array[0] + "\\" + array[array.Length - 1];
				if (!imageResourceCache.resourcesByFileName.ContainsKey(text))
				{
					imageResourceCache.resourcesByFileName.Add(text, (Stream)streamEnumerator.Value);
				}
			}
			else if (text.EndsWith(".svg", StringComparison.Ordinal))
			{
				imageResourceCache.resources.Add(text, (Stream)streamEnumerator.Value);
				string[] array = ImageCacheUtils.Split(text);
				string text2 = array[array.Length - 1];
				string text3 = array[1];
				if (array[0] != "svgimages")
				{
					text3 = array[0] + "\\" + text3;
				}
				if (!imageResourceCache.categoryResources.TryGetValue(text3, out var value))
				{
					value = new Dictionary<string, Stream>(256);
					imageResourceCache.categoryResources.Add(text3, value);
				}
				if (!value.ContainsKey(text2))
				{
					value.Add(text2, (Stream)streamEnumerator.Value);
				}
				imageResourceCache.svgImages.Add(text2.Substring(0, text2.Length - 4));
				text = array[0] + "\\" + text2;
				if (!imageResourceCache.resourcesByFileName.ContainsKey(text))
				{
					imageResourceCache.resourcesByFileName.Add(text, (Stream)streamEnumerator.Value);
				}
			}
		}
		return imageResourceCache;
	}
}
internal sealed class ImageResourceKey : IEquatable<ImageResourceKey>
{
	private readonly string Name;

	private readonly string Prefix;

	private readonly string Category;

	private readonly int hash;

	public ImageResourceKey(string name, string prefix, string category)
	{
		Name = name;
		Prefix = prefix;
		Category = category;
		hash = HashCodeHelper.CalculateGeneric(Name, Prefix, Category);
	}

	public bool Equals(ImageResourceKey key)
	{
		if (this == key)
		{
			return true;
		}
		if (string.Equals(Name, key.Name) && string.Equals(Prefix, key.Prefix))
		{
			return string.Equals(Category, key.Category);
		}
		return false;
	}

	public sealed override bool Equals(object obj)
	{
		if (!(obj is ImageResourceKey objB))
		{
			return false;
		}
		return object.Equals(this, objB);
	}

	public sealed override int GetHashCode()
	{
		return hash;
	}
}
internal static class ImageCacheUtils
{
	private static readonly char[] splitCharacters = new char[2] { '\\', '/' };

	internal const string ColoredCategory = "images";

	internal const string DevAVCategory = "devav";

	internal const string GrayScaledCategory = "grayscaleimages";

	internal const string Office2013Category = "office2013";

	internal const string BlazorCategory = "blazorimages";

	internal const string SvgCategory = "svgimages";

	public static readonly string SvgImageSuffix = ".svg";

	public static readonly string ImageSuffix = "_16x16.png";

	public static readonly string LargeImageSuffix = "_32x32.png";

	public static bool IsMatch(string key, string prefix, string fileName, ImageType imageType)
	{
		return IsMatch(key, prefix, fileName, GetCategory(imageType));
	}

	public static bool IsMatch(string key, string prefix, string fileName, string category)
	{
		if (!key.EndsWith(fileName, StringComparison.Ordinal))
		{
			return false;
		}
		string[] array = Split(key);
		bool flag = array[0].Equals(category, StringComparison.Ordinal) && array[array.Length - 1].Equals(fileName, StringComparison.Ordinal);
		if (!string.IsNullOrEmpty(prefix))
		{
			flag &= key.IndexOf(prefix, 0, StringComparison.Ordinal) >= 0;
		}
		return flag;
	}

	[MethodImpl(MethodImplOptions.AggressiveInlining)]
	public static string[] Split(string key)
	{
		return key.Split(splitCharacters);
	}

	public static void ExtractPrefix(ref string key, out string prefix)
	{
		prefix = string.Empty;
		if (!string.IsNullOrEmpty(key))
		{
			string[] array = Split(key);
			if (array.Length > 1)
			{
				prefix = array[0].ToLowerInvariant();
				key = array[array.Length - 1];
			}
		}
	}

	internal static string GetCategory(ImageType imageType)
	{
		return imageType switch
		{
			ImageType.Colored => "images", 
			ImageType.DevAV => "devav", 
			ImageType.GrayScaled => "grayscaleimages", 
			ImageType.Office2013 => "office2013", 
			ImageType.Svg => "svgimages", 
			ImageType.Blazor => "blazorimages", 
			_ => throw new ArgumentException("imageType"), 
		};
	}

	public static string GetFileName(string id, ImageSize imageSize, ImageType imageType)
	{
		if (imageType == ImageType.Svg || imageType == ImageType.Blazor)
		{
			return id + SvgImageSuffix;
		}
		if (imageSize == ImageSize.Size16x16)
		{
			return id + ImageSuffix;
		}
		return id + LargeImageSuffix;
	}
}
