public static class ImageCollectionHelper
{
	private static Dictionary<ImageType, string> folders = new Dictionary<ImageType, string>
	{
		{
			ImageType.Colored,
			"Images"
		},
		{
			ImageType.GrayScaled,
			"GrayScaleImages"
		},
		{
			ImageType.Office2013,
			"Office2013"
		},
		{
			ImageType.DevAV,
			"DevAV"
		},
		{
			ImageType.Svg,
			"SvgImages"
		},
		{
			ImageType.Blazor,
			"BlazorImages"
		}
	};

	internal static ImageType[] IncompleteFolderKeys = new ImageType[2]
	{
		ImageType.DevAV,
		ImageType.Blazor
	};

	private static IList<string> folderList = null;

	public static readonly string ResourceName = "DevExpress.Images.v23.2.g.resources";

	private static IList<string> IncompleteFolderList
	{
		get
		{
			if (folderList == null)
			{
				folderList = (from element in folders
					where IncompleteFolderKeys.Contains(element.Key)
					select element.Value).ToList();
			}
			return folderList;
		}
	}

	internal static int ImagesCountForName => (folders.Keys.Except(IncompleteFolderKeys).Count() - 1) * 2;

	public static bool IsIncompleteFolder(string item)
	{
		return false;
	}

	public static string GetImageFolderName(ImageType imageType)
	{
		return folders[imageType];
	}

	public static ImageType? GetImageTypeByFolderName(string folderName)
	{
		KeyValuePair<ImageType, string> keyValuePair = folders.FirstOrDefault((KeyValuePair<ImageType, string> x) => x.Value == folderName);
		if (!(keyValuePair.Value != folderName))
		{
			return keyValuePair.Key;
		}
		return null;
	}

	public static ImageType GetImageType(string key)
	{
		KeyValuePair<ImageType, string> keyValuePair = folders.FirstOrDefault((KeyValuePair<ImageType, string> x) => x.Key != ImageType.Colored && key.IndexOf(x.Value, StringComparison.OrdinalIgnoreCase) >= 0);
		if (keyValuePair.Value != null && key.IndexOf(keyValuePair.Value, StringComparison.OrdinalIgnoreCase) >= 0)
		{
			return keyValuePair.Key;
		}
		return ImageType.Colored;
	}
}
public class ImagesAssemblyImageInfo : IDXImageInfo
{
	internal const string PackPrefix = "pack://application:,,,";

	private const string Delimeter = "/";

	private const string UriPrefix = "pack://application:,,,/DevExpress.Images.v23.2;component/";

	private string shortUri;

	private string uri;

	public string Group { get; private set; }

	public ImageType ImageType { get; private set; }

	public string Name { get; private set; }

	public ImageSize Size { get; private set; }

	public string[] Tags { get; private set; }

	internal static Dictionary<string, List<ImagesAssemblyImageInfo>> BuildCache(IEnumerable<ImagesAssemblyImageInfo> images, bool keysInLowerCase = true)
	{
		Dictionary<string, List<ImagesAssemblyImageInfo>> dictionary = new Dictionary<string, List<ImagesAssemblyImageInfo>>();
		foreach (ImagesAssemblyImageInfo image in images)
		{
			if (ImageCollectionHelper.IncompleteFolderKeys.Contains(image.ImageType) || !IsBrowsable(image.MakeUriShort().ToLowerInvariant()))
			{
				continue;
			}
			int num = image.Name.IndexOf("_");
			if (num < 0 || (!image.Name.EndsWith("_16x16.png") && !image.Name.EndsWith("_32x32.png")) || image.Name.Contains("-") || image.Name.Contains("%"))
			{
				LogInconsistentImage(image);
			}
			else if (image.Name.IndexOf("_", num + 1) < 0)
			{
				string text = image.Name.Substring(0, image.Name.IndexOf("_"));
				if (keysInLowerCase)
				{
					text = text.ToLowerInvariant();
				}
				if (!dictionary.TryGetValue(text, out var value))
				{
					value = (dictionary[text] = new List<ImagesAssemblyImageInfo>());
				}
				value.Add(image);
			}
		}
		Dictionary<string, List<ImagesAssemblyImageInfo>> dictionary2 = new Dictionary<string, List<ImagesAssemblyImageInfo>>();
		foreach (KeyValuePair<string, List<ImagesAssemblyImageInfo>> item in dictionary)
		{
			bool flag = true;
			foreach (ImagesAssemblyImageInfo item2 in item.Value)
			{
				if (item2.Group != item.Value[0].Group)
				{
					flag = false;
				}
			}
			if (!flag)
			{
				LogInconsistentImage(item.Value.ToArray());
			}
			else if (item.Value.Count >= ImageCollectionHelper.ImagesCountForName)
			{
				dictionary2[item.Key] = item.Value;
			}
		}
		return dictionary2;
	}

	internal static bool IsBrowsable(string key)
	{
		return !HiddenKeysStorage.Default.Contains(key);
	}

	private static void LogInconsistentImage(params ImagesAssemblyImageInfo[] images)
	{
	}

	public ImagesAssemblyImageInfo(string group, ImageType imageType, string name, ImageSize size, string[] tags)
	{
		Group = group;
		ImageType = imageType;
		Name = name;
		Size = size;
		Tags = tags;
	}

	public string MakeUri()
	{
		if (uri == null)
		{
			uri = "pack://application:,,,/DevExpress.Images.v23.2;component/" + MakeUriShort();
		}
		return uri;
	}

	internal string MakeUriShort()
	{
		if (shortUri == null)
		{
			shortUri = ImageCollectionHelper.GetImageFolderName(ImageType) + "/" + Group + "/" + Name;
		}
		return shortUri;
	}
}
public class HiddenKeysStorage
{
	private Dictionary<string, bool> storage;

	private static HiddenKeysStorage instanceCore;

	public static HiddenKeysStorage Default
	{
		get
		{
			if (instanceCore == null)
			{
				instanceCore = new HiddenKeysStorage();
				Initialize(instanceCore);
			}
			return instanceCore;
		}
	}

	private Dictionary<string, bool> Storage => storage;

	protected HiddenKeysStorage()
	{
		storage = new Dictionary<string, bool>();
	}

	private static void Initialize(HiddenKeysStorage instance)
	{
		instance.Storage.Add("grayscaleimages/edit/remove_16x16.png", value: true);
		instance.Storage.Add("grayscaleimages/edit/remove_32x32.png", value: true);
		instance.Storage.Add("grayscaleimages/edit/new_16x16.png", value: true);
		instance.Storage.Add("grayscaleimages/edit/new_32x32.png", value: true);
		instance.Storage.Add("grayscaleimages/actions/delete_16x16.png", value: true);
		instance.Storage.Add("grayscaleimages/actions/delete_32x32.png", value: true);
		instance.Storage.Add("grayscaleimages/actions/openfile_16x16.png", value: true);
		instance.Storage.Add("grayscaleimages/actions/openfile_32x32.png", value: true);
	}

	public bool Contains(string key)
	{
