public interface IAssemblyImageReader : IEnumerable, IDisposable
{
	IDictionaryEnumerator GetStreamEnumerator();
}
public abstract class AssemblyImageReaderBase : IAssemblyImageReader, IEnumerable, IDisposable
{
	private readonly Assembly assembly;

	protected AssemblyImageReaderBase(Assembly assembly)
	{
		Guard.ArgumentNotNull(assembly, "assembly");
		this.assembly = assembly;
	}

	IEnumerator IEnumerable.GetEnumerator()
	{
		return CreateEnumerator(assembly);
	}

	IDictionaryEnumerator IAssemblyImageReader.GetStreamEnumerator()
	{
		return CreateEnumerator(assembly);
	}

	void IDisposable.Dispose()
	{
		Dispose();
	}

	protected virtual void Dispose()
	{
	}

	protected abstract IDictionaryEnumerator CreateEnumerator(Assembly assembly);
}
public sealed class AssemblyImageReader : AssemblyImageReaderBase
{
	private readonly ResourceReader coreReader;

	[SecuritySafeCritical]
	public AssemblyImageReader(Assembly assembly)
		: base(assembly)
	{
		coreReader = new ResourceReader(assembly.GetManifestResourceStream(ImageCollectionHelper.ResourceName));
	}

	protected override IDictionaryEnumerator CreateEnumerator(Assembly assembly)
	{
		return coreReader.GetEnumerator();
	}

	protected override void Dispose()
	{
		coreReader.Dispose();
	}
}
public sealed class AssemblyEmbeddedImageReader : AssemblyImageReaderBase
{
	private sealed class EmbeddedImageEnumerator : IDictionaryEnumerator, IEnumerator
	{
		private DictionaryEntry entry;

		private int imageIndex;

		private readonly string[] names;

		private readonly Assembly assembly;

		DictionaryEntry IDictionaryEnumerator.Entry => entry;

		object IEnumerator.Current => entry;

		object IDictionaryEnumerator.Key => entry.Key;

		object IDictionaryEnumerator.Value => entry.Value;

		internal EmbeddedImageEnumerator(Assembly assembly)
		{
			Guard.ArgumentNotNull(assembly, "assembly");
			imageIndex = -1;
			this.assembly = assembly;
			names = assembly.GetManifestResourceNames();
		}

		void IEnumerator.Reset()
		{
			imageIndex = -1;
		}

		bool IEnumerator.MoveNext()
		{
			if (imageIndex >= names.Length - 1)
			{
				return false;
			}
			string text = names[++imageIndex];
			entry = new DictionaryEntry(EmbeddedResourceHelper.BuildResourceKey(text), assembly.GetManifestResourceStream(text));
			return true;
		}
	}

	private static class EmbeddedResourceHelper
	{
		public static string BuildResourceKey(string key)
		{
			return BuildResourceKeyCore(Path.GetFileNameWithoutExtension(key), Path.GetExtension(key));
		}

		private static string BuildResourceKeyCore(string @base, string extension)
		{
			string key = SkipPrefix(@base, "DevExpress.Images.");
			key = Encode(key);
			return (key.Replace('.', '/') + extension).ToLowerInvariant();
		}

		private static string SkipPrefix(string s, string prefix)
		{
			if (s.StartsWith(prefix))
			{
				return s.Substring(prefix.Length);
			}
			return s;
		}

		private static string Encode(string key)
		{
			key = key.Replace("%", "%25").Replace(" ", "%20");
			if (!key.Contains("."))
			{
				return key;
			}
			int num = key.LastIndexOf('.');
			string text = key.Substring(0, num);
			return text.Replace("_", "%20") + key.Substring(num);
		}
	}

	public AssemblyEmbeddedImageReader(Assembly assembly)
		: base(assembly)
	{
	}

	protected override IDictionaryEnumerator CreateEnumerator(Assembly assembly)
	{
		return new EmbeddedImageEnumerator(assembly);
	}
}
public class DXImageServicesImp : IDXImagesProviderEx, IDXImagesProvider
{
	public string GetFile(string name, ImageSize imageSize, ImageType imageType)
	{
		IEnumerable<string> urisByName = ImagesAssemblyImageList.GetUrisByName(name);
		return urisByName.FirstOrDefault((string x) => ImageCollectionHelper.GetImageType(x) == imageType && imageSize switch
		{
			ImageSize.Any => true, 
			ImageSize.Size16x16 => x.EndsWith("/" + name + "_16x16.png", StringComparison.OrdinalIgnoreCase), 
			ImageSize.Size32x32 => x.EndsWith("/" + name + "_32x32.png", StringComparison.OrdinalIgnoreCase), 
			_ => throw new NotImplementedException(), 
		});
	}

	public Image GetImage(string id, ImageSize imageSize, ImageType imageType)
	{
		return ImageResourceCache.Default.GetImageById(id, imageSize, imageType);
	}

	public IEnumerable<string> GetFiles(string name)
	{
		foreach (ImagesAssemblyImageInfo imagesAssemblyImageInfo in ImagesAssemblyImageList.Images)
		{
			string text = imagesAssemblyImageInfo.MakeUri();
			if (text.IndexOf(name, StringComparison.OrdinalIgnoreCase) != -1 && text.EndsWith(".png", StringComparison.OrdinalIgnoreCase))
			{
				yield return text;
			}
		}
	}

	public bool IsGrayScaledImage(string key)
	{
		return ImageCollectionHelper.GetImageType(key) == ImageType.GrayScaled;
	}

	public bool IsOffice2013Image(string key)
	{
		return ImageCollectionHelper.GetImageType(key) == ImageType.Office2013;
	}

	public bool IsDevAVImage(string key)
	{
		return ImageCollectionHelper.GetImageType(key) == ImageType.DevAV;
	}

	public bool IsBrowsable(string key)
	{
		return ImagesAssemblyImageInfo.IsBrowsable(key);
	}

	public IDXImageInfo[] GetAllImages()
	{
		return ImagesAssemblyImageList.Images;
	}

	public string[] GetBaseImages()
	{
		FieldInfo[] fields = typeof(DXImages).GetFields(BindingFlags.Static | BindingFlags.Public);
		IEnumerable<string> source = from field in fields
			let val = field.GetValue(null).ToString()
			where field.FieldType == typeof(string)
			orderby val
			select val;
		return source.ToArray();
	}

	public Image GetSvgImage(string id, ISvgPaletteProvider paletteProvider, int width = 32, int height = 32)
	{
		return ImageResourceCache.Default.GetSvgImageById(id, paletteProvider, width, height);
	}

	public IEnumerable<string> GetSvgImages()
	{
		return ImageResourceCache.Default.SvgImages;
	}

	public Image GetImageByPath(string path)
	{
		return ImageResourceCache.Default.GetImage(path);
	}

	public SvgImage GetSvgImageByPath(string path)
	{
		return ImageResourceCache.Default.GetSvgImage(path);
	}

	public SvgImage GetSvgImage(string id)
	{
		return ImageResourceCache.Default.GetSvgImageById(id);
	}
}
